   171→// TranscriptPosition holds the position information for a Gemini transcript
   172→type TranscriptPosition struct {
   173→	MessageCount int // Total number of messages
   174→}
   175→
   176→// GetTranscriptPosition reads a Gemini transcript file and returns the message count.
   177→// Returns empty position if file doesn't exist or is empty.
   178→// For Gemini, position is based on message count (not lines like Claude Code's JSONL).
   179→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
   180→	if path == "" {
   181→		return TranscriptPosition{}, nil
   182→	}
   183→
   184→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
   185→	if err != nil {
   186→		if os.IsNotExist(err) {
   187→			return TranscriptPosition{}, nil
   188→		}
   189→		return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
   190→	}
   191→
   192→	if len(data) == 0 {
   193→		return TranscriptPosition{}, nil
   194→	}
   195→
   196→	transcript, err := ParseTranscript(data)
   197→	if err != nil {
   198→		return TranscriptPosition{}, fmt.Errorf("failed to parse transcript: %w", err)
   199→	}
   200→
   201→	return TranscriptPosition{
   202→		MessageCount: len(transcript.Messages),
   203→	}, nil
   204→}
