   206→// TokenUsage represents aggregated token usage for a checkpoint
   207→type TokenUsage struct {
   208→	// InputTokens is the number of input tokens (fresh, not from cache)
   209→	InputTokens int `json:"input_tokens"`
   210→	// OutputTokens is the number of output tokens generated
   211→	OutputTokens int `json:"output_tokens"`
   212→	// CacheReadTokens is the number of tokens read from cache
   213→	CacheReadTokens int `json:"cache_read_tokens"`
   214→	// APICallCount is the number of API calls made
   215→	APICallCount int `json:"api_call_count"`
   216→}
   217→
   218→// CalculateTokenUsage calculates token usage from a Gemini transcript.
   219→// This is specific to Gemini's API format where each message may have a tokens object
   220→// with input, output, cached, thoughts, tool, and total counts.
   221→// Only processes messages from startMessageIndex onwards (0-indexed).
   222→func CalculateTokenUsage(data []byte, startMessageIndex int) *TokenUsage {
   223→	var transcript struct {
   224→		Messages []geminiMessageWithTokens `json:"messages"`
   225→	}
   226→
   227→	if err := json.Unmarshal(data, &transcript); err != nil {
   228→		return &TokenUsage{}
   229→	}
   230→
   231→	usage := &TokenUsage{}
   232→
   233→	for i, msg := range transcript.Messages {
   234→		// Skip messages before startMessageIndex
   235→		if i < startMessageIndex {
   236→			continue
   237→		}
   238→
   239→		// Only count tokens from gemini (assistant) messages
   240→		if msg.Type != MessageTypeGemini {
   241→			continue
   242→		}
   243→
   244→		if msg.Tokens == nil {
   245→			continue
   246→		}
   247→
   248→		usage.APICallCount++
   249→		usage.InputTokens += msg.Tokens.Input
   250→		usage.OutputTokens += msg.Tokens.Output
   251→		usage.CacheReadTokens += msg.Tokens.Cached
   252→	}
   253→
   254→	return usage
   255→}
   256→
   257→// CalculateTokenUsageFromFile calculates token usage from a Gemini transcript file.
   258→// If startMessageIndex > 0, only considers messages from that index onwards.
   259→func CalculateTokenUsageFromFile(path string, startMessageIndex int) (*TokenUsage, error) {
   260→	if path == "" {
   261→		return &TokenUsage{}, nil
   262→	}
   263→
   264→	data, err := os.ReadFile(path) //nolint:gosec // Reading from controlled transcript path
   265→	if err != nil {
   266→		if os.IsNotExist(err) {
   267→			return &TokenUsage{}, nil
   268→		}
   269→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   270→	}
   271→
   272→	return CalculateTokenUsage(data, startMessageIndex), nil
   273→}
