   570→// handleGeminiBeforeAgent handles the BeforeAgent hook for Gemini CLI.
   571→// This is equivalent to Claude Code's UserPromptSubmit - it fires when the user submits a prompt.
   572→// We capture the initial state here so we can track what files were modified during the session.
   573→// It also checks for concurrent sessions and blocks if another session has uncommitted changes.
   574→func handleGeminiBeforeAgent() error {
   575→	// Always use the Gemini agent for Gemini hooks (don't use GetAgent() which may
   576→	// return Claude based on auto-detection in environments like VSCode)
   577→	ag, err := agent.Get("gemini")
   578→	if err != nil {
   579→		return fmt.Errorf("failed to get gemini agent: %w", err)
   580→	}
   581→
   582→	// Parse hook input - BeforeAgent provides user prompt info similar to UserPromptSubmit
   583→	input, err := ag.ParseHookInput(agent.HookUserPromptSubmit, os.Stdin)
   584→	if err != nil {
   585→		return fmt.Errorf("failed to parse hook input: %w", err)
   586→	}
   587→
   588→	logCtx := logging.WithAgent(logging.WithComponent(context.Background(), "hooks"), ag.Name())
   589→
   590→	// Log with prompt if available (Gemini provides the user's prompt in BeforeAgent)
   591→	logArgs := []any{
   592→		slog.String("hook", "before-agent"),
   593→		slog.String("hook_type", "agent"),
   594→		slog.String("model_session_id", input.SessionID),
   595→		slog.String("transcript_path", input.SessionRef),
   596→	}
   597→	if input.UserPrompt != "" {
   598→		// Truncate long prompts for logging
   599→		promptPreview := input.UserPrompt
   600→		if len(promptPreview) > 100 {
   601→			promptPreview = promptPreview[:100] + "..."
   602→		}
   603→		logArgs = append(logArgs, slog.String("prompt_preview", promptPreview))
   604→	}
   605→	logging.Info(logCtx, "gemini-before-agent", logArgs...)
   606→
   607→	if input.SessionID == "" {
   608→		return errors.New("no session_id in input")
   609→	}
   610→
   611→	// Get the Entire session ID
   612→	entireSessionID := paths.EntireSessionID(input.SessionID)
   613→
   614→	// Check for concurrent sessions before proceeding
   615→	// This will output a blocking response and exit if there's a conflict (first time only)
   616→	// On subsequent prompts, it proceeds normally (both sessions create interleaved checkpoints)
   617→	checkConcurrentSessionsGemini(entireSessionID)
   618→
   619→	// Capture pre-prompt state with transcript position (Gemini-specific)
   620→	// This captures both untracked files and the current transcript message count
   621→	// so we can calculate token usage for just this prompt/response cycle
   622→	if err := CaptureGeminiPrePromptState(entireSessionID, input.SessionRef); err != nil {
   623→		return fmt.Errorf("failed to capture pre-prompt state: %w", err)
   624→	}
   625→
