   138→// ExtractLastUserPrompt extracts the last user message from transcript
   139→func ExtractLastUserPrompt(lines []TranscriptLine) string {
   140→	for i := len(lines) - 1; i >= 0; i-- {
   141→		if lines[i].Type != "user" {
   142→			continue
   143→		}
   144→
   145→		var msg userMessage
   146→		if err := json.Unmarshal(lines[i].Message, &msg); err != nil {
   147→			continue
   148→		}
   149→
   150→		// Handle string content
   151→		if str, ok := msg.Content.(string); ok {
   152→			return str
   153→		}
   154→
   155→		// Handle array content (text blocks)
   156→		if arr, ok := msg.Content.([]interface{}); ok {
   157→			var texts []string
   158→			for _, item := range arr {
   159→				if m, ok := item.(map[string]interface{}); ok {
   160→					if m["type"] == "text" {
   161→						if text, ok := m["text"].(string); ok {
   162→							texts = append(texts, text)
   163→						}
   164→					}
   165→				}
   166→			}
   167→			if len(texts) > 0 {
   168→				return strings.Join(texts, "\n\n")
   169→			}
   170→		}
   171→	}
   172→	return ""
   173→}
