   248→		usage.APICallCount++
   249→		usage.InputTokens += msg.Tokens.Input
   250→		usage.OutputTokens += msg.Tokens.Output
   251→		usage.CacheReadTokens += msg.Tokens.Cached
   252→	}
   253→
   254→	return usage
