   149→// HasOtherActiveSessionsWithCheckpoints checks if there are other active sessions
   150→// from the SAME worktree (different from currentSessionID) that have created checkpoints
   151→// on the SAME base commit (current HEAD). This is used to detect concurrent sessions
   152→// in different terminals but same directory.
   153→// Returns the first found session with CheckpointCount > 0, or nil if none found.
   154→func (s *ManualCommitStrategy) HasOtherActiveSessionsWithCheckpoints(currentSessionID string) (*SessionState, error) {
   155→	currentWorktree, err := GetWorktreePath()
   156→	if err != nil {
   157→		return nil, err
   158→	}
   159→
   160→	// Get current HEAD to compare with session base commits
   161→	repo, err := OpenRepository()
   162→	if err != nil {
   163→		return nil, err
   164→	}
   165→	head, err := repo.Head()
   166→	if err != nil {
   167→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
   168→	}
   169→	currentHead := head.Hash().String()
   170→
   171→	allStates, err := s.listAllSessionStates()
   172→	if err != nil {
   173→		return nil, err
   174→	}
   175→
   176→	for _, state := range allStates {
   177→		// Only consider sessions from the same worktree with checkpoints
   178→		// AND based on the same commit (current HEAD)
   179→		// Sessions from different base commits are independent and shouldn't trigger warning
   180→		if state.SessionID != currentSessionID &&
   181→			state.WorktreePath == currentWorktree &&
   182→			state.CheckpointCount > 0 &&
   183→			state.BaseCommit == currentHead {
   184→			return state, nil
   185→		}
   186→	}
   187→	return nil, nil //nolint:nilnil // nil,nil indicates no other session found (expected case)
   188→}
