    98→// Load loads the session state for the given session ID.
    99→// Returns (nil, nil) when session file doesn't exist (not an error condition).
   100→func (s *StateStore) Load(ctx context.Context, sessionID string) (*State, error) {
   101→	_ = ctx // Reserved for future use
   102→
   103→	// Validate session ID to prevent path traversal
   104→	if err := paths.ValidateSessionID(sessionID); err != nil {
   105→		return nil, fmt.Errorf("invalid session ID: %w", err)
   106→	}
   107→
   108→	stateFile := s.stateFilePath(sessionID)
   109→
   110→	data, err := os.ReadFile(stateFile) //nolint:gosec // stateFile is derived from sessionID
   111→	if os.IsNotExist(err) {
   112→		return nil, nil //nolint:nilnil // nil,nil indicates session not found (expected case)
   113→	}
   114→	if err != nil {
   115→		return nil, fmt.Errorf("failed to read session state: %w", err)
   116→	}
   117→
   118→	var state State
   119→	if err := json.Unmarshal(data, &state); err != nil {
   120→		return nil, fmt.Errorf("failed to unmarshal session state: %w", err)
   121→	}
   122→	return &state, nil
   123→}
