   125→// Save saves the session state atomically.
   126→func (s *StateStore) Save(ctx context.Context, state *State) error {
   127→	_ = ctx // Reserved for future use
   128→
   129→	// Validate session ID to prevent path traversal
   130→	if err := paths.ValidateSessionID(state.SessionID); err != nil {
   131→		return fmt.Errorf("invalid session ID: %w", err)
   132→	}
   133→
   134→	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
   135→		return fmt.Errorf("failed to create session state directory: %w", err)
   136→	}
   137→
   138→	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
   139→	if err != nil {
   140→		return fmt.Errorf("failed to marshal session state: %w", err)
   141→	}
   142→
   143→	stateFile := s.stateFilePath(state.SessionID)
   144→
   145→	// Atomic write: write to temp file, then rename
   146→	tmpFile := stateFile + ".tmp"
   147→	if err := os.WriteFile(tmpFile, data, 0o600); err != nil {
   148→		return fmt.Errorf("failed to write session state: %w", err)
   149→	}
   150→	if err := os.Rename(tmpFile, stateFile); err != nil {
   151→		return fmt.Errorf("failed to rename session state file: %w", err)
   152→	}
   153→	return nil
   154→}
