   176→// List returns all session states.
   177→func (s *StateStore) List(ctx context.Context) ([]*State, error) {
   178→	_ = ctx // Reserved for future use
   179→
   180→	entries, err := os.ReadDir(s.stateDir)
   181→	if os.IsNotExist(err) {
   182→		return nil, nil
   183→	}
   184→	if err != nil {
   185→		return nil, fmt.Errorf("failed to read session state directory: %w", err)
   186→	}
   187→
   188→	var states []*State
   189→	for _, entry := range entries {
   190→		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") {
   191→			continue
   192→		}
   193→		if strings.HasSuffix(entry.Name(), ".tmp") {
   194→			continue // Skip temp files
   195→		}
   196→
   197→		sessionID := strings.TrimSuffix(entry.Name(), ".json")
   198→		state, err := s.Load(ctx, sessionID)
   199→		if err != nil {
   200→			continue // Skip corrupted state files
   201→		}
   202→		if state == nil {
   203→			continue
   204→		}
   205→
   206→		states = append(states, state)
   207→	}
   208→	return states, nil
   209→}
