   252→	ctx := context.Background()
   253→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
   254→	cmd.Dir = "."
   255→	output, err := cmd.Output()
   256→	if err != nil {
   257→		return "", fmt.Errorf("failed to get git common dir: %w", err)
   258→	}
   259→
   260→	commonDir := strings.TrimSpace(string(output))
   261→
   262→	// git rev-parse --git-common-dir returns relative paths from the working directory,
   263→	// so we need to make it absolute if it isn't already
   264→	if !filepath.IsAbs(commonDir) {
   265→		commonDir = filepath.Join(".", commonDir)
   266→	}
   267→
   268→	return filepath.Clean(commonDir), nil
   269→}
