   271→// GetWorktreePath returns the absolute path to the current worktree root.
   272→func GetWorktreePath() (string, error) {
   273→	ctx := context.Background()
   274→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--show-toplevel")
   275→	output, err := cmd.Output()
   276→	if err != nil {
   277→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   278→	}
